CREATE TABLE document_control.management_reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id uuid NOT NULL REFERENCES core.organizations(id),
  record_number integer GENERATED ALWAYS AS IDENTITY UNIQUE,
  title text NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 4000),
  held_on date NOT NULL, start_time text NOT NULL DEFAULT '', end_time text NOT NULL DEFAULT '',
  location text NOT NULL CHECK (length(trim(location)) BETWEEN 1 AND 4000),
  period_start date, period_end date, next_review_on date,
  chair_user_id uuid REFERENCES identity.users(id),
  attendees jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(attendees) = 'array' AND jsonb_array_length(attendees) <= 100),
  agenda jsonb NOT NULL CHECK (jsonb_typeof(agenda) = 'array'),
  suitability text NOT NULL DEFAULT '', adequacy text NOT NULL DEFAULT '', effectiveness text NOT NULL DEFAULT '',
  improvement_decisions text NOT NULL DEFAULT '', qms_changes text NOT NULL DEFAULT '', resource_decisions text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'Draft' CHECK (status IN ('Draft', 'For Approval', 'Approved')),
  approved_at timestamptz, approved_by_user_id uuid REFERENCES identity.users(id), approval_notes text NOT NULL DEFAULT '',
  version integer NOT NULL DEFAULT 1,
  source_key text, source_payload jsonb,
  created_by_user_id uuid REFERENCES identity.users(id),
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id), UNIQUE (organization_id, source_key),
  CHECK (period_start IS NULL OR period_end IS NULL OR period_start <= period_end),
  CHECK (status <> 'Approved' OR (approved_at IS NOT NULL AND approved_by_user_id IS NOT NULL AND length(trim(approval_notes)) > 0))
);
CREATE INDEX management_reviews_register ON document_control.management_reviews (organization_id, held_on DESC);

CREATE TABLE document_control.management_review_actions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id),
  record_number integer GENERATED ALWAYS AS IDENTITY UNIQUE,
  origin_meeting_id uuid NOT NULL, topic_key text NOT NULL,
  description text NOT NULL CHECK (length(trim(description)) BETWEEN 1 AND 4000),
  expected_outcome text NOT NULL DEFAULT '', department text NOT NULL DEFAULT '',
  owner_user_id uuid REFERENCES identity.users(id), due_on date,
  priority text NOT NULL DEFAULT 'Not assessed' CHECK (priority IN ('Not assessed', 'Low', 'Medium', 'High')),
  evidence_reference text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'Open' CHECK (status IN ('Open', 'In Progress', 'Completed', 'Closed')),
  completion_notes text NOT NULL DEFAULT '', evidence_location text NOT NULL DEFAULT '', effectiveness_notes text NOT NULL DEFAULT '',
  completed_at timestamptz, completed_by_user_id uuid REFERENCES identity.users(id),
  closed_at timestamptz, closed_by_user_id uuid REFERENCES identity.users(id),
  version integer NOT NULL DEFAULT 1, source_payload jsonb,
  created_by_user_id uuid REFERENCES identity.users(id),
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (organization_id, id),
  FOREIGN KEY (organization_id, origin_meeting_id) REFERENCES document_control.management_reviews (organization_id, id),
  CHECK (status <> 'Closed' OR (completed_at IS NOT NULL AND completed_by_user_id IS NOT NULL AND closed_at IS NOT NULL
    AND closed_by_user_id IS NOT NULL AND length(trim(completion_notes)) > 0 AND length(trim(evidence_location)) > 0
    AND length(trim(effectiveness_notes)) > 0 AND length(trim(expected_outcome)) > 0 AND owner_user_id IS NOT NULL AND due_on IS NOT NULL))
);
CREATE INDEX management_review_actions_pending ON document_control.management_review_actions (organization_id, status, due_on);
CREATE INDEX management_review_actions_owner ON document_control.management_review_actions (owner_user_id);

CREATE TABLE document_control.management_review_action_reviews (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id),
  meeting_id uuid NOT NULL, action_id uuid NOT NULL,
  notes text NOT NULL CHECK (length(trim(notes)) BETWEEN 1 AND 4000),
  action_snapshot jsonb NOT NULL CHECK (jsonb_typeof(action_snapshot) = 'object'),
  reviewed_by_user_id uuid REFERENCES identity.users(id), reviewed_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (meeting_id, action_id),
  FOREIGN KEY (organization_id, meeting_id) REFERENCES document_control.management_reviews (organization_id, id),
  FOREIGN KEY (organization_id, action_id) REFERENCES document_control.management_review_actions (organization_id, id)
);
GRANT SELECT, INSERT, UPDATE ON document_control.management_reviews, document_control.management_review_actions,
  document_control.management_review_action_reviews TO mrmpl_web;
GRANT USAGE, SELECT ON SEQUENCE document_control.management_reviews_record_number_seq,
  document_control.management_review_actions_record_number_seq TO mrmpl_web;
GRANT SELECT ON document_control.management_reviews, document_control.management_review_actions,
  document_control.management_review_action_reviews TO mrmpl_reporting;

INSERT INTO identity.permissions (key, module, name, description) VALUES
  ('iso.management_review.read', 'iso-document', 'View all management reviews', 'View meetings, minutes, action reviews, history and the shared pending list.'),
  ('iso.management_review.manage', 'iso-document', 'Prepare management reviews', 'Prepare meetings, record participation/discussion and assign or carry forward actions.'),
  ('iso.management_review.approve', 'iso-document', 'QA approve management review minutes', 'Approve/return minutes or reopen approved minutes with a reason. Does not close actions.'),
  ('iso.management_review.verify', 'iso-document', 'QA verify management review actions', 'Check evidence/effectiveness, close actions or return/reopen work.');
INSERT INTO identity.role_permissions (role_id, permission_id)
SELECT role.id, permission.id FROM identity.roles role CROSS JOIN identity.permissions permission
WHERE (role.key IN ('administrator', 'quality-assurance-hod') AND permission.key LIKE 'iso.management_review.%')
  OR (role.key = 'department-manager' AND permission.key = 'iso.management_review.read')
ON CONFLICT DO NOTHING;

